'use client';

import { useState, useEffect, useRef } from 'react';
import { Plus, Search, PlusSquare, Edit2, Trash2, Tag, Layers, Code, Palette, Type, Square, LayoutTemplate, Bold, Italic, Underline, AlignLeft, AlignCenter, AlignRight, AlignJustify, Image as ImageIcon, Link as LinkIcon, Move } from 'lucide-react';
import { useTranslations } from 'next-intl';
import ConfirmDialog from '@/app/components/ConfirmDialog';
import toast from 'react-hot-toast';

interface Snippet {
    id: string;
    name: string;
    category: string;
    htmlContent: string;
    thumbnail: string | null;
}

export default function SnippetsManagement() {
    const t = useTranslations('Admin');
    const commonT = useTranslations('Common');
    const [snippets, setSnippets] = useState<Snippet[]>([]);
    const [loading, setLoading] = useState(true);
    const [showModal, setShowModal] = useState(false);
    const [isEditing, setIsEditing] = useState(false);
    const [currentId, setCurrentId] = useState<string | null>(null);
    const [deleteId, setDeleteId] = useState<string | null>(null);

    // Form state
    const [name, setName] = useState('');
    const [category, setCategory] = useState('Intro');
    const [htmlContent, setHtmlContent] = useState('');

    // Visual Editor State (Modal)
    const [viewMode, setViewMode] = useState<'visual' | 'code'>('visual');
    const [activeElement, setActiveElement] = useState<HTMLElement | null>(null);
    const previewRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        fetchSnippets();
    }, []);

    const fetchSnippets = async () => {
        try {
            const res = await fetch('/api/snippets');
            const data = await res.json();
            setSnippets(data);
        } catch (error) {
            console.error('Failed to fetch snippets:', error);
            toast.error('Failed to load snippets');
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        // Ensure we capture final visual state if in visual mode
        let finalContent = htmlContent;
        if (viewMode === 'visual' && previewRef.current) {
            // Clean artifacts
            const clone = previewRef.current.cloneNode(true) as HTMLElement;
            const editables = clone.querySelectorAll('[contenteditable]');
            editables.forEach(el => el.removeAttribute('contenteditable'));
            const outlines = clone.querySelectorAll('*');
            outlines.forEach(el => {
                (el as HTMLElement).style.outline = '';
                (el as HTMLElement).style.outlineOffset = '';
            });
            finalContent = clone.innerHTML;
        }

        try {
            const apiUrl = isEditing ? `/api/snippets/${currentId}` : '/api/snippets';
            const method = isEditing ? 'PUT' : 'POST';

            const res = await fetch(apiUrl, {
                method,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ name, category, htmlContent: finalContent }),
            });
            if (res.ok) {
                closeModal();
                fetchSnippets();
                toast.success(isEditing ? commonT('saved') : commonT('created'));
            } else {
                toast.error('Operation failed');
            }
        } catch (error) {
            console.error(`Failed to ${isEditing ? 'update' : 'create'} snippet:`, error);
            toast.error('An error occurred');
        }
    };

    const handleDeleteClick = (id: string) => {
        setDeleteId(id);
    };

    const confirmDelete = async () => {
        if (!deleteId) return;
        try {
            const res = await fetch(`/api/snippets/${deleteId}`, { method: 'DELETE' });
            if (res.ok) {
                fetchSnippets();
                toast.success(commonT('deleted'));
            } else {
                toast.error('Failed to delete');
            }
        } catch (error) {
            console.error('Failed to delete snippet:', error);
            toast.error('Failed to delete');
        }
    };

    const openEditModal = (snippet: Snippet) => {
        setName(snippet.name);
        setCategory(snippet.category);
        setHtmlContent(snippet.htmlContent);
        setCurrentId(snippet.id);
        setIsEditing(true);
        setViewMode('visual'); // Default to visual
        setShowModal(true);
    };

    const closeModal = () => {
        setShowModal(false);
        setIsEditing(false);
        setName('');
        setCategory('Intro');
        setHtmlContent('');
        setCurrentId(null);
        setActiveElement(null);
    };

    // Visual Editing Logic
    const handlePreviewClick = (e: React.MouseEvent) => {
        e.stopPropagation();
        const target = e.target as HTMLElement;

        if (activeElement) {
            activeElement.style.outline = '';
        }

        setActiveElement(target);
        target.style.outline = '2px solid #3b82f6';
        target.style.outlineOffset = '2px';

        // Enable editing for text-like elements
        const textTags = ['P', 'H1', 'H2', 'H3', 'H4', 'H5', 'H6', 'SPAN', 'DIV', 'A', 'LI', 'BUTTON', 'LABEL', 'B', 'I', 'U', 'STRONG', 'EM', 'SMALL', 'SUB', 'SUP', 'BLOCKQUOTE', 'PRE', 'CODE', 'TD', 'TH', 'CAPTION', 'FIGCAPTION', 'DT', 'DD', 'ADDRESS'];

        if (textTags.includes(target.tagName)) {
            target.contentEditable = 'true';
            target.style.outline = 'none'; // Remove outline so it looks like pure text editing
            target.focus();

            // Auto-update HTML content on interaction end
            const updateHtml = () => {
                if (previewRef.current) {
                    setHtmlContent(previewRef.current.innerHTML);
                }
            };
            target.onblur = () => {
                target.contentEditable = 'false'; // Clean up
                // We might want to restore outline here if it's still "selected" conceptually, 
                // but usually blur means we are done.
                // However, our activeElement state might still be this element.
                // If we want to indicate selection persists, we'd add outline back.
                // But for "edit text", usually we are done.
                updateHtml();
            };
            target.oninput = () => {
                // optional live update
            };
        }
    };

    const applyStyle = (prop: string, val: string) => {
        if (activeElement) {
            activeElement.style[prop as any] = val;
            if (previewRef.current) {
                setHtmlContent(previewRef.current.innerHTML);
            }
        }
    };

    return (
        <div className="space-y-8">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-bold text-slate-900">{t('snippets')}</h1>
                    <p className="text-slate-500 mt-1">{t('readymadeSections')}</p>
                </div>
                <button
                    onClick={() => {
                        setIsEditing(false);
                        setShowModal(true);
                        setViewMode('visual');
                    }}
                    className="flex items-center gap-2 bg-primary text-white px-5 py-2.5 rounded-xl font-semibold hover:bg-primary-dark transition-colors shadow-sm"
                >
                    <Plus className="w-5 h-5" />
                    {t('newSnippet')}
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {loading ? (
                    [1, 2, 3].map(i => (
                        <div key={i} className="bg-white rounded-2xl h-48 animate-pulse shadow-sm border border-slate-200"></div>
                    ))
                ) : snippets.length === 0 ? (
                    <div className="col-span-full py-20 bg-white border border-dashed border-slate-300 rounded-3xl text-center">
                        <PlusSquare className="w-12 h-12 text-slate-300 mx-auto mb-4" />
                        <h3 className="text-lg font-bold text-slate-900">{t('noSnippets')}</h3>
                        <p className="text-slate-500">{t('snippetsDescription')}</p>
                    </div>
                ) : snippets.map((snippet) => (
                    <div key={snippet.id} className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden group hover:shadow-md transition-shadow">
                        <div className="aspect-video bg-slate-100 flex items-center justify-center p-6 border-b border-slate-100 relative overflow-hidden">
                            <div className="text-slate-400 text-xs scale-75 origin-top opacity-50 pointer-events-none select-none w-full h-full overflow-hidden">
                                <div dangerouslySetInnerHTML={{ __html: snippet.htmlContent }} />
                            </div>
                            <div className="absolute top-3 right-3 rtl:left-3 rtl:right-auto">
                                <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider bg-white text-primary shadow-xs border border-primary/20">
                                    <Tag className="w-2.5 h-2.5" />
                                    {snippet.category}
                                </span>
                            </div>
                        </div>
                        <div className="p-5 flex justify-between items-center">
                            <div>
                                <h3 className="font-bold text-slate-900">{snippet.name}</h3>
                                <p className="text-xs text-slate-500 flex items-center gap-1 mt-0.5">
                                    <Layers className="w-3 h-3" />
                                    {t('htmlFragment')}
                                </p>
                            </div>
                            <div className="flex gap-1">
                                <button
                                    onClick={() => openEditModal(snippet)}
                                    className="p-2 text-slate-400 hover:text-primary transition-colors"
                                    title={commonT('edit')}
                                >
                                    <Edit2 className="w-4 h-4" />
                                </button>
                                <button
                                    onClick={() => handleDeleteClick(snippet.id)}
                                    className="p-2 text-slate-400 hover:text-red-500 transition-colors"
                                    title={commonT('delete')}
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-xs flex items-center justify-center p-4 z-50">
                    <div className="bg-white rounded-2xl w-full max-w-5xl shadow-2xl border border-slate-200 max-h-[90vh] flex flex-col">
                        <div className="p-6 border-b border-slate-100 flex justify-between items-center flex-shrink-0">
                            <h2 className="text-xl font-bold text-slate-900">
                                {isEditing ? t('editSnippet') : t('createSnippet')}
                            </h2>
                            <button onClick={closeModal} className="text-slate-400 hover:text-slate-600">&times;</button>
                        </div>

                        <div className="flex-1 overflow-hidden flex flex-col md:flex-row">
                            {/* Settings Sidebar */}
                            <div className="w-full md:w-80 bg-slate-50 p-6 border-r border-slate-100 flex-shrink-0 overflow-y-auto">
                                <form id="snippet-form" onSubmit={handleSubmit} className="space-y-6">
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1">{t('snippetName')}</label>
                                        <input
                                            type="text"
                                            value={name}
                                            onChange={(e) => setName(e.target.value)}
                                            required
                                            className="w-full px-4 py-2 border border-slate-200 rounded-lg bg-white"
                                            placeholder="e.g. Hero Section"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-slate-700 mb-1">{t('category')}</label>
                                        <select
                                            value={category}
                                            onChange={(e) => setCategory(e.target.value)}
                                            className="w-full px-4 py-2 border border-slate-200 rounded-lg bg-white"
                                        >
                                            {['Intro', 'Content', 'Features', 'Contact', 'Footer', 'Header', 'CTA'].map(c => (
                                                <option key={c} value={c}>{c}</option>
                                            ))}
                                        </select>
                                    </div>

                                    <hr className="border-slate-200" />

                                    {/* Visual Controls */}
                                    {activeElement && viewMode === 'visual' ? (
                                        <div className="space-y-6 animate-in fade-in duration-200">
                                            {/* Selection Info / Navigation */}
                                            <div className="space-y-2">
                                                <div className="flex items-center justify-between">
                                                    <div className="text-xs font-mono bg-slate-200 p-1.5 rounded text-slate-600 truncate max-w-[150px]">
                                                        &lt;{activeElement.tagName.toLowerCase()}&gt;
                                                    </div>
                                                    {activeElement.parentElement && activeElement.parentElement !== previewRef.current && (
                                                        <button
                                                            type="button"
                                                            onClick={() => {
                                                                if (activeElement.parentElement) {
                                                                    if (activeElement.isContentEditable) activeElement.contentEditable = 'false';
                                                                    const parent = activeElement.parentElement;
                                                                    setActiveElement(parent);
                                                                    parent.style.outline = '2px solid #3b82f6';
                                                                    parent.style.outlineOffset = '2px';
                                                                    // Clear child outline? No, react state update will handle it naturally if we only show outline for active
                                                                }
                                                            }}
                                                            className="text-[10px] bg-indigo-50 text-indigo-600 px-2 py-1 rounded hover:bg-indigo-100 flex items-center gap-1"
                                                        >
                                                            <Layers className="w-3 h-3" /> Parent
                                                        </button>
                                                    )}
                                                </div>
                                            </div>

                                            {/* Link Properties */}
                                            {activeElement.tagName === 'A' && (
                                                <div className="space-y-3 p-3 bg-blue-50 rounded-lg border border-blue-100">
                                                    <label className="text-sm font-semibold text-blue-800 flex items-center gap-2">
                                                        <LinkIcon className="w-4 h-4" /> Link Properties
                                                    </label>
                                                    <div>
                                                        <label className="block text-xs text-blue-600 mb-1">Target URL</label>
                                                        <input
                                                            type="text"
                                                            value={activeElement.getAttribute('href') || ''}
                                                            onChange={(e) => {
                                                                activeElement.setAttribute('href', e.target.value);
                                                                if (previewRef.current) setHtmlContent(previewRef.current.innerHTML);
                                                            }}
                                                            className="w-full text-xs p-2 border border-blue-200 rounded text-blue-900"
                                                            placeholder="https://..."
                                                        />
                                                    </div>
                                                </div>
                                            )}

                                            {/* Spacing */}
                                            <div>
                                                <label className="flex items-center gap-2 text-xs font-bold text-slate-500 mb-2 uppercase tracking-wider">
                                                    <Move className="w-3 h-3" /> Spacing
                                                </label>
                                                <div className="grid grid-cols-2 gap-3">
                                                    <div>
                                                        <label className="block text-[10px] text-slate-500 mb-1">Padding</label>
                                                        <input
                                                            type="range" min="0" max="48" step="2"
                                                            defaultValue={parseInt(activeElement.style.padding || '0')}
                                                            className="w-full accent-indigo-600"
                                                            onChange={(e) => applyStyle('padding', `${e.target.value}px`)}
                                                        />
                                                    </div>
                                                    <div>
                                                        <label className="block text-[10px] text-slate-500 mb-1">Margin</label>
                                                        <input
                                                            type="range" min="0" max="48" step="2"
                                                            defaultValue={parseInt(activeElement.style.margin || '0')}
                                                            className="w-full accent-indigo-600"
                                                            onChange={(e) => applyStyle('margin', `${e.target.value}px`)}
                                                        />
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Typography */}
                                            {activeElement.tagName !== 'IMG' && (
                                                <div className="space-y-3">
                                                    <label className="flex items-center gap-2 text-xs font-bold text-slate-500 uppercase tracking-wider">
                                                        <Type className="w-3 h-3" /> Typography
                                                    </label>

                                                    {/* Color */}
                                                    <div className="flex gap-1.5 flex-wrap">
                                                        {['#000000', '#ffffff', '#ef4444', '#f59e0b', '#10b981', '#3b82f6', '#8b5cf6'].map(c => (
                                                            <button
                                                                key={c}
                                                                type="button"
                                                                onMouseDown={(e) => {
                                                                    e.preventDefault();
                                                                    if (document.queryCommandSupported('foreColor') && window.getSelection()?.toString()) {
                                                                        document.execCommand('foreColor', false, c);
                                                                        if (previewRef.current) setHtmlContent(previewRef.current.innerHTML);
                                                                    } else {
                                                                        applyStyle('color', c);
                                                                    }
                                                                }}
                                                                className="w-6 h-6 rounded-full border border-slate-300 shadow-xs hover:scale-110"
                                                                style={{ backgroundColor: c }}
                                                            />
                                                        ))}
                                                        <input type="color" className="w-6 h-6 p-0 rounded-full border-0" onChange={(e) => applyStyle('color', e.target.value)} />
                                                    </div>

                                                    {/* Styles */}
                                                    <div className="flex gap-1 bg-slate-100 p-1 rounded-lg">
                                                        <button type="button" onMouseDown={(e) => { e.preventDefault(); document.execCommand('bold'); if (previewRef.current) setHtmlContent(previewRef.current.innerHTML); }} className="p-1.5 hover:bg-white rounded"><Bold className="w-3.5 h-3.5 text-slate-600" /></button>
                                                        <button type="button" onMouseDown={(e) => { e.preventDefault(); document.execCommand('italic'); if (previewRef.current) setHtmlContent(previewRef.current.innerHTML); }} className="p-1.5 hover:bg-white rounded"><Italic className="w-3.5 h-3.5 text-slate-600" /></button>
                                                        <button type="button" onMouseDown={(e) => { e.preventDefault(); document.execCommand('underline'); if (previewRef.current) setHtmlContent(previewRef.current.innerHTML); }} className="p-1.5 hover:bg-white rounded"><Underline className="w-3.5 h-3.5 text-slate-600" /></button>
                                                        <div className="w-px bg-slate-300 mx-1"></div>
                                                        <button type="button" onClick={() => applyStyle('textAlign', 'left')} className="p-1.5 hover:bg-white rounded"><AlignLeft className="w-3.5 h-3.5 text-slate-600" /></button>
                                                        <button type="button" onClick={() => applyStyle('textAlign', 'center')} className="p-1.5 hover:bg-white rounded"><AlignCenter className="w-3.5 h-3.5 text-slate-600" /></button>
                                                        <button type="button" onClick={() => applyStyle('textAlign', 'right')} className="p-1.5 hover:bg-white rounded"><AlignRight className="w-3.5 h-3.5 text-slate-600" /></button>
                                                    </div>
                                                </div>
                                            )}

                                            {/* Background */}
                                            <div>
                                                <label className="flex items-center gap-2 text-xs font-bold text-slate-500 mb-2 uppercase tracking-wider">
                                                    <Square className="w-3 h-3" /> Background
                                                </label>
                                                <div className="flex gap-1.5 flex-wrap">
                                                    {['transparent', '#ffffff', '#f8fafc', '#1e293b', '#fca5a5', '#93c5fd'].map(c => (
                                                        <button
                                                            key={c}
                                                            type="button"
                                                            onClick={() => applyStyle('backgroundColor', c)}
                                                            className="w-6 h-6 rounded-full border border-slate-300 shadow-xs hover:scale-110 relative"
                                                            style={{ backgroundColor: c === 'transparent' ? 'white' : c }}
                                                        >
                                                            {c === 'transparent' && <div className="absolute inset-0 border-r border-red-500 rotate-45 transform origin-center" />}
                                                        </button>
                                                    ))}
                                                    <input type="color" className="w-6 h-6 p-0 rounded-full overflow-hidden border-0" onChange={(e) => applyStyle('backgroundColor', e.target.value)} />
                                                </div>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="text-sm text-slate-400 italic">
                                            {viewMode === 'visual' ? 'Select an element to edit style' : 'Switch to Visual mode to edit styles'}
                                        </div>
                                    )}
                                </form>
                            </div>

                            {/* Main Content Area */}
                            <div className="flex-1 flex flex-col min-h-[400px] md:h-auto">
                                <div className="bg-white border-b border-slate-200 px-4 py-2 flex items-center gap-4">
                                    <div className="flex bg-slate-100 rounded-lg p-1">
                                        <button
                                            type="button"
                                            onClick={() => setViewMode('visual')}
                                            className={`px-3 py-1.5 text-xs font-semibold rounded-md flex items-center gap-2 transition-all ${viewMode === 'visual' ? 'bg-white shadow-sm text-primary' : 'text-slate-500 hover:text-slate-700'}`}
                                        >
                                            <LayoutTemplate className="w-3.5 h-3.5" /> Visual
                                        </button>
                                        <button
                                            type="button"
                                            onClick={() => setViewMode('code')}
                                            className={`px-3 py-1.5 text-xs font-semibold rounded-md flex items-center gap-2 transition-all ${viewMode === 'code' ? 'bg-white shadow-sm text-primary' : 'text-slate-500 hover:text-slate-700'}`}
                                        >
                                            <Code className="w-3.5 h-3.5" /> Code
                                        </button>
                                    </div>
                                </div>

                                <div className="flex-1 overflow-auto bg-slate-100 p-8 relative">
                                    {viewMode === 'visual' ? (
                                        <div
                                            ref={previewRef}
                                            className="bg-white shadow-sm min-h-full rounded-lg border border-slate-200 p-4"
                                            onClick={handlePreviewClick}
                                            dangerouslySetInnerHTML={{ __html: htmlContent }}
                                        />
                                    ) : (
                                        <textarea
                                            value={htmlContent}
                                            onChange={(e) => setHtmlContent(e.target.value)}
                                            className="w-full h-full p-4 font-mono text-sm bg-slate-900 text-slate-100 resize-none focus:outline-none"
                                            spellCheck={false}
                                        />
                                    )}
                                </div>
                            </div>
                        </div>

                        <div className="p-4 border-t border-slate-100 bg-white rounded-b-2xl flex justify-end gap-3 flex-shrink-0">
                            <button
                                type="button"
                                onClick={closeModal}
                                className="px-5 py-2.5 border border-slate-200 text-slate-600 rounded-xl font-bold hover:bg-slate-50 transition-colors"
                            >
                                {commonT('cancel')}
                            </button>
                            <button
                                onClick={handleSubmit}
                                className="px-5 py-2.5 bg-primary text-white rounded-xl font-bold hover:bg-primary-dark transition-colors shadow-lg shadow-primary/30"
                            >
                                {isEditing ? commonT('saveChanges') : commonT('create')}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            <ConfirmDialog
                isOpen={!!deleteId}
                onClose={() => setDeleteId(null)}
                onConfirm={confirmDelete}
                title={commonT('delete')}
                message={commonT('confirmDelete')}
                isDeleting
            />
        </div>
    );
}
